 const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#386f79');g.addColorStop(.58,'#b7b68f');g.addColorStop(.59,'#d0b77f');g.addColorStop(1,'#476b55');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 for(let i=0;i<10;i++){let x=i*112+(t*11%112);line(x,300,x+40,298,'#fff0c544',2)}
 // broken tide stones
 for(let i=0;i<5;i++){let x=74+i*52,y=398+(i%2)*18;ellipse(x,y,24,7,'#705f4b');rr(x-18,y-8,36,9,3,'#9b8763','#c1ab7d')}
 // foes
 if(enemy){let x=638,y=260;ellipse(x,y+47,67,17,'#162a3066');ctx.save();ctx.translate(x,y);let bob=Math.sin(t*2.7)*5;
 // spectral tide wraith
 ctx.fillStyle='#153e4c';ctx.beginPath();ctx.moveTo(-49,31);ctx.quadraticCurveTo(-66,-9,-41,-34);ctx.quadraticCurveTo(-23,-63,12,-50);ctx.quadraticCurveTo(55,-34,47,10);ctx.lineTo(59,33);ctx.lineTo(36,24);ctx.lineTo(18,39);ctx.lineTo(-2,25);ctx.lineTo(-24,43);ctx.lineTo(-38,28);ctx.closePath();ctx.fill();
 ctx.fillStyle='#56a6a4';ctx.beginPath();ctx.moveTo(-39,24);ctx.quadraticCurveTo(-23,-34,3,-42);ctx.quadraticCurveTo(40,-33,38,12);ctx.lineTo(20,21);ctx.lineTo(2,13);ctx.lineTo(-15,29);ctx.closePath();ctx.fill();ellipse(-14,-10,5,8,'#ecdb9b');ellipse(17,-12,5,8,'#ecdb9b');ellipse(-14,-9,2,4,'#203c44');ellipse(17,-11,2,4,'#203c44');ctx.strokeStyle='#b8e3cf';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-8,7);ctx.quadraticCurveTo(1,13,10,5);ctx.stroke();for(let i=0;i<6;i++)ellipse(Math.sin(t+i*4)*60,Math.cos(t*1.4+i*3)*45,2,3,'#c7ebd8');ctx.restore();
 // enemy HP
 rr(541,146,197,17,5,'#102632dd','#e5cc91');ctx.fillStyle='#be665e';ctx.fillRect(545,150,189*Math.max(0,enemy.hp/enemy.max),9);text('SILENT WRAITH',640,139,11,'#f8e9be','center');}
 // party heroes in battle positions
 const fighters=[{x:286,y:303,c:'#d48a53',name:'You'},{x:205,y:345,c:'#e6ad68',name:'Luma'},{x:369,y:357,c:'#83b8a5',name:'Bram'}];fighters.forEach((f,i)=>{ellipse(f.x,f.y+24,22,7,'#18292a55');let bob=Math.sin(t*4+i*1.6)*2;ctx.fillStyle=f.c;ctx.beginPath();ctx.arc(f.x,f.y-14+bob,9,0,6.3);ctx.fill();ctx.fillStyle=i===0?'#16434b':i===1?'#8f5364':'#3e665e';ctx.beginPath();ctx.moveTo(f.x-10,f.y-6+bob);ctx.lineTo(f.x+10,f.y-6+bob);ctx.lineTo(f.x+13,f.y+21);ctx.lineTo(f.x-12,f.y+21);ctx.fill();if(i===0){line(f.x+12,f.y-3,f.x+27,f.y-21,'#ead08b',3);ellipse(f.x+28,f.y-22,3,3,'#fbebae')}else if(i===1){ctx.strokeStyle='#f0c77e';ctx.lineWidth=3;ctx.beginPath();ctx.arc(f.x,f.y+3,18,0,Math.PI*2);ctx.stroke()}else{line(f.x-14,f.y-8,f.x-25,f.y+15,'#afc2a8',4)}});
}
function render(){ctx.clearRect(0,0,W,H);if(mode==='battle'||mode==='victory')drawBattle();else drawWorld();}
function nearby(){let candidates=npcs.filter(n=>Math.hypot(n.x-hero.x,n.y-hero.y)<57);return candidates.sort((a,b)=>Math.hypot(a.x-hero.x,a.y-hero.y)-Math.hypot(b.x-hero.x,b.y-hero.y))[0]}
function setDialog(name,lines,done){dialogue=lines;dialogIndex=0;dialogDone=done||null;ui.speaker.textContent=name;ui.line.textContent=dialogue[0];ui.dialog.classList.remove('hidden');ui.prompt.classList.add('hidden');mode='dialog'}
let dialogDone=null;
function advanceDialog(){if(mode!=='dialog')return;if(dialogIndex<dialogue.length-1){dialogIndex++;ui.line.textContent=dialogue[dialogIndex]}else{ui.dialog.classList.add('hidden');let fn=dialogDone;dialogDone=null;mode='explore';if(fn)fn()}}
function interact(){if(mode==='dialog'){advanceDialog();return}if(mode!=='explore')return;let n=nearby();if(!n){showToast('The tide-path glimmers in the sunlight.');return}if(n.kind==='elder'){
 if(quest===0){setDialog('Mira, keeper of the shore',['You came with the morning tide. I knew the sea would send someone.','The shrine has gone quiet. Since then, even the waves have lost their names.','Follow the lanterns, little wayfarer. Listen for what the silence is hiding.'],()=>{quest=1;ui.objective.textContent='Reach the tide shrine at the end of the stone path.'})}
 else if(quest===1)setDialog('Mira',['The old stones remember the first song. Stand still, and they may remember you.']);
 else setDialog('Mira',['There! The surf is singing again. You have given our island back its dawn.','When the sea calls, may you always know the way home.'],()=>showEnding());
 }else if(n.kind==='shrine'){
 if(quest===0)setDialog('The Tide Shrine',['A hush settles over the shore. A pale shape stirs behind the altar.','Perhaps the keeper in the village knows how to approach this place.']);
 else if(quest===1)startBattle();else setDialog('The Tide Shrine',['Its crystal glows with the soft rhythm of the waves.']);
 }}
function startBattle(){mode='battle';returnMode='explore';enemy={hp:106,max:106};battleTurn=0;hero.guard=false;ui.hud.classList.add('hidden');ui.battle.classList.remove('hidden');ui.battleLog.textContent='A Silent Wraith rises from the tide!';updateParty();updateCommands()}
function updateParty(){const all=[{name:'You',role:'Wayfarer',hp:hero.hp,max:100,mp:hero.mp,maxmp:36},...companions];ui.party.innerHTML=all.map((p,i)=>`<div class="member"><strong style="color:${i===0?'#f5dda4':companions[i-1].color}">${p.name} · ${p.role}</strong><div class="stat"><span>HP</span><span>${p.hp}/${p.max}</span></div><div class="bar"><i style="width:${100*p.hp/p.max}%"></i></div><div class="stat"><span>MP</span><span>${p.mp}/${p.maxmp}</span></div><div class="bar mp"><i style="width:${100*p.mp/p.maxmp}%"></i></div></div>`).join('')}
function updateCommands(){document.querySelectorAll('.cmd').forEach(b=>{b.disabled=actionLock>0||(b.dataset.action==='spell'&&hero.mp<8)||(b.dataset.action==='potion'&&hero.potions<1)})}
function combatAction(action){if(mode!=='battle'||actionLock>0)return;actionLock=1;let msg='';
 if(action==='attack'){let d=18+Math.floor(Math.random()*11);enemy.hp-=d;msg=`You strike the wraith for ${d} damage.`}
 if(action==='spell'){if(hero.mp<8){actionLock=0;return}hero.mp-=8;let d=32+Math.floor(Math.random()*12);enemy.hp-=d;msg=`Tidecall! A ribbon of water deals ${d} damage.`}
 if(action==='potion'){if(!hero.potions){actionLock=0;return}hero.potions--;let target=[{name:'You',obj:hero,max:100},...companions.map(c=>({name:c.name,obj:c,max:c.max}))].filter(x=>x.obj.hp<x.max).sort((a,b)=>a.obj.hp/a.max-b.obj.hp/b.max)[0];if(!target){hero.potions++;actionLock=0;ui.battleLog.textContent='Everyone is already at full health.';return}let heal=Math.min(42,target.max-target.obj.hp);target.obj.hp+=heal;msg=`A moonberry restores ${heal} HP to ${target.name}.`}
 if(action==='guard'){hero.guard=true;msg='You brace yourself. The next blow will be softened.'}
 ui.battleLog.textContent=msg;updateParty();updateCommands();
 if(enemy.hp<=0){setTimeout(victory,700);return}
 setTimeout(()=>enemyTurn(),780)
}
function enemyTurn(){if(mode!=='battle')return;let team=[{name:'You',obj:hero},...companions].filter(p=>p.obj.hp>0);if(!team.length){hero.hp=54;companions.forEach(c=>c.hp=Math.max(36,c.hp));ui.battleLog.textContent='The tide carries you back to shore. Your party catches its breath.';setTimeout(()=>{ui.battle.classList.add('hidden');ui.hud.classList.remove('hidden');mode='explore';hero.x=598;hero.y=299;updateParty()},1300);return}let target=team[Math.floor(Math.random()*team.length)],d=12+Math.floor(Math.random()*10);if(target.obj===hero&&hero.guard){d=Math.floor(d*.35);hero.guard=false}target.obj.hp=Math.max(0,target.obj.hp-d);ui.battleLog.textContent=`The wraith lashes out! ${target.name} takes ${d} damage.`;shake=9;updateParty();setTimeout(()=>{actionLock=0;updateCommands()},650)}
function victory(){if(mode!=='battle')return;mode='victory';enemy.hp=0;ui.battleLog.textContent='The wraith dissolves into a thousand drops of light.';ui.objective.textContent='Return to Mira with the shrine’s crystal.';quest=2;hero.mp=Math.min(36,hero.mp+10);companions.forEach(c=>{c.hp=Math.min(c.max,c.hp+18);c.mp=Math.min(c.maxmp,c.mp+8)});updateParty();setTimeout(()=>{ui.battle.classList.add('hidden');ui.hud.classList.remove('hidden');mode='explore';showToast('Shrine restored · The sea remembers its song')},1200)}
function showToast(message){let old=document.querySelector('.toast');if(old)old.remove();let el=document.createElement('div');el.className='toast';el.textContent=message;document.getElementById('game').appendChild(el);setTimeout(()=>el.remove(),3100)}
function showEnding(){ui.start.classList.remove('hidden');ui.start.innerHTML='<section class="card"><div class="eyebrow">Auralis remembers</div><h2>The sea sings again</h2><div class="rule"></div><p>The tide rolls in, bright with morning. Mira smiles as the old island song rises from the water — and your small journey becomes part of its melody.</p><p style="color:#edcf91">Thank you for playing Tidebound.</p><button class="goldbtn" id="again">Wander the shore</button><div class="hint">Your adventure is complete · Explore freely or return to the shrine</div></section>';document.getElementById('again').onclick=()=>{ui.start.classList.add('hidden');ui.hud.classList.remove('hidden');mode='explore'}}
function showMenu(){if(mode==='title')return;if(ui.start.classList.contains('hidden')){ui.start.classList.remove('hidden');ui.start.innerHTML='<section class="card"><div class="eyebrow">The shore is waiting</div><h2>Journey paused</h2><div class="rule"></div><p>Take a breath. The waves are patient.</p><button class="goldbtn" id="resume">Return to the shore</button><div class="hint">WASD / arrows to move · E / Space to interact</div></section>';document.getElementById('resume').onclick=()=>{ui.start.classList.add('hidden');mode='explore'}}}

function step(dt){t+=dt;if(mode==='explore'){let dx=0,dy=0;if(keys.ArrowLeft||keys.a||keys.A)dx--;if(keys.ArrowRight||keys.d||keys.D)dx++;if(keys.ArrowUp||keys.w||keys.W)dy--;if(keys.ArrowDown||keys.s||keys.S)dy++;if(dx||dy){let len=Math.hypot(dx,dy);hero.x=clamp(hero.x+dx/len*dt*145,25,935);hero.y=clamp(hero.y+dy/len*dt*120,235,510);hero.walk+=dt*9;hero.dir=dx<0?0:dx>0?1:hero.dir}let n=nearby();if(n){ui.prompt.textContent=`E  ·  ${n.kind==='elder'?'Speak with Mira':'Examine the Tide Shrine'}`;ui.prompt.classList.remove('hidden')}else ui.prompt.classList.add('hidden')}if(shake>0)shake=Math.max(0,shake-dt*20)}
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;step(dt);if(shake>0){ctx.save();ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake)}render();if(shake>0)ctx.restore();requestAnimationFrame(frame)}
document.getElementById('begin').addEventListener('click',()=>{ui.start.classList.add('hidden');ui.hud.classList.remove('hidden');mode='explore';setDialog('Mira, keeper of the shore',['The sea has gone quiet, and the old tide-shrine has lost its light.','Speak to me in the village, then follow the lantern path. Perhaps the waves will tell you what they have forgotten.'],()=>{ui.objective.textContent='Speak with Mira, the keeper of the shore.'})});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.repeat)return;if(e.key==='Escape'){showMenu();return}if(mode==='dialog'&&(e.key==='e'||e.key==='E'||e.key===' '||e.key==='Enter')){advanceDialog();return}if(mode==='explore'&&(e.key==='e'||e.key==='E'||e.key===' '||e.key==='Enter')){interact();return}if(mode==='battle'){if(e.key==='1')combatAction('attack');if(e.key==='2')combatAction('spell');if(e.key==='3')combatAction('potion');if(e.key==='4')combatAction('guard')}});
window.addEventListener('keyup',e=>{keys[e.key]=false});window.addEventListener('blur',()=>keys={});
document.querySelectorAll('.cmd').forEach(b=>b.addEventListener('click',()=>combatAction(b.dataset.action)));
const dirMap={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'};document.querySelectorAll('[data-dir]').forEach(b=>{let key=dirMap[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[key]=false))});
document.getElementById('actTouch').addEventListener('pointerdown',e=>{e.preventDefault();if(mode==='dialog')advanceDialog();else if(mode==='explore')interact()});ui.dialog.addEventListener('click',advanceDialog);
// Keep action controls above the world on touch; tapping anywhere in the game never scrolls the page.
document.getElementById('game').addEventListener('contextmenu',e=>e.preventDefault());
requestAnimationFrame(frame);
</script></body></html>

