function showMenu(){if(mode!=='explore'||!ui.start.classList.contains('hidden'))return;ui.start.classList.remove('hidden');ui.start.innerHTML='<section class="card"><div class="eyebrow">The shore is waiting</div><h2>Journey paused</h2><div class="rule"></div><p>Take a breath. The waves are patient.</p><button class="goldbtn" id="resume">Return to the shore</button><div class="hint">WASD / arrows to move · E / Space to interact</div></section>';document.getElementById('resume').onclick=()=>{ui.start.classList.add('hidden');mode='explore'}}
function step(dt){t+=dt;if(mode==='explore'){let dx=0,dy=0;if(keys.ArrowLeft||keys.a||keys.A)dx--;if(keys.ArrowRight||keys.d||keys.D)dx++;if(keys.ArrowUp||keys.w||keys.W)dy--;if(keys.ArrowDown||keys.s||keys.S)dy++;if(dx||dy){let len=Math.hypot(dx,dy);hero.x=clamp(hero.x+dx/len*dt*145,25,935);hero.y=clamp(hero.y+dy/len*dt*120,235,510);hero.walk+=dt*9;hero.dir=dx<0?0:dx>0?1:hero.dir}let n=nearby();if(n){ui.prompt.textContent=`E  ·  ${n.kind==='elder'?'Speak with Mira':'Examine the Tide Shrine'}`;ui.prompt.classList.remove('hidden')}else ui.prompt.classList.add('hidden')}if(shake>0)shake=Math.max(0,shake-dt*20)}
function frame(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;step(dt);if(shake>0){ctx.save();ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake)}render();if(shake>0)ctx.restore();requestAnimationFrame(frame)}
document.getElementById('begin').addEventListener('click',()=>{ui.start.classList.add('hidden');ui.hud.classList.remove('hidden');mode='explore';setDialog('Mira, keeper of the shore',['The sea has gone quiet, and the old tide-shrine has lost its light.','Speak to me in the village, then follow the lantern path. Perhaps the waves will tell you what they have forgotten.'],()=>{ui.objective.textContent='Speak with Mira, the keeper of the shore.'})});
window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();keys[e.key]=true;if(e.repeat)return;if(e.key==='Escape'){showMenu();return}if(mode==='dialog'&&(e.key==='e'||e.key==='E'||e.key===' '||e.key==='Enter')){advanceDialog();return}if(mode==='explore'&&(e.key==='e'||e.key==='E'||e.key===' '||e.key==='Enter')){interact();return}if(mode==='battle'){if(e.key==='1')combatAction('attack');if(e.key==='2')combatAction('spell');if(e.key==='3')combatAction('potion');if(e.key==='4')combatAction('guard')}});window.addEventListener('keyup',e=>{keys[e.key]=false});window.addEventListener('blur',()=>keys={});document.querySelectorAll('.cmd').forEach(b=>b.addEventListener('click',()=>combatAction(b.dataset.action)));
const dirMap={up:'ArrowUp',down:'ArrowDown',left:'ArrowLeft',right:'ArrowRight'};document.querySelectorAll('[data-dir]').forEach(b=>{let key=dirMap[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();keys[key]=true;b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[key]=false))});document.getElementById('actTouch').addEventListener('pointerdown',e=>{e.preventDefault();if(mode==='dialog')advanceDialog();else if(mode==='explore')interact()});ui.dialog.addEventListener('click',advanceDialog);document.getElementById('game').addEventListener('contextmenu',e=>e.preventDefault());requestAnimationFrame(frame);
</script></body></html>

